insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('gaz_kondenz_radiator', 'Kondenzációs gázkazán + radiátor 55/45 + indirekt HMV tároló', 'Fűtött téren belüli kondenzációs kazán, kétcsöves radiátoros fűtés termosztatikus szelepekkel, fordulatszám-szabályozott szivattyú; HMV indirekt tárolóval, cirkuláció nélkül.', '{"hotermelo":{"tipus":"kazan_tabla","kazan":"kondenzacios","hely":"belul","energiahordozo":"fosszilis_gaz"},"szabalyozas":{"valasztas":{"alap":"ref_helyiseg_pi","holeado":{"tipus":"szabad","hofok":"55/45","hatarolo":"kulsofali"},"helyiseg":"termosztatikus","beszabalyozas":{"csovek":"ketcsoves","mod":"statikus_csoportos_nelkul","holeadokTobbMint10":false}}},"elosztas":{"hely":"belul","elore":55,"vissza":45},"tarolo":null,"szivattyu":"fordulatszam_szabad_10K"}'::jsonb, '{"hotermelo":{"tipus":"kazan_tabla","kazan":"kondenzacios","energiahordozo":"fosszilis_gaz"},"tarolo":{"tipus":"indirekt","hely":"belul"},"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['csaladi_haz','kockahaz_felujitott','uj_epulet'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('gaz_kond_kombi', 'Kondenzációs gáz kombikazán (átfolyós HMV) + radiátor 55/45', 'Lakásonkénti vagy családi házas kondenzációs kombikazán, átfolyós HMV készítéssel (V < 2 l), termosztatikus szelepek.', '{"hotermelo":{"tipus":"kazan_tabla","kazan":"kondenzacios","hely":"belul","energiahordozo":"fosszilis_gaz"},"szabalyozas":{"valasztas":{"alap":"ref_helyiseg_pi","holeado":{"tipus":"szabad","hofok":"55/45","hatarolo":"kulsofali"},"helyiseg":"termosztatikus","beszabalyozas":{"csovek":"ketcsoves","mod":"statikus_csoportos_nelkul","holeadokTobbMint10":false}}},"elosztas":{"hely":"belul","elore":55,"vissza":45},"tarolo":null,"szivattyu":"fordulatszam_szabad_10K"}'::jsonb, '{"hotermelo":{"tipus":"kazan_tabla","kazan":"kond_kombi_AF","energiahordozo":"fosszilis_gaz"},"tarolo":null,"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['tegla_tarsashaz','blokkos_tarsashaz','csaladi_haz'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('gaz_hagyomanyos_regi', 'Régi állandó hőmérsékletű gázkazán + radiátor 90/70 + gázbojler', 'Meglévő épületek tipikus régi rendszere: állandó hőmérsékletű kazán, szabályozás nélküli radiátorok, beszabályozás nélkül, állandó fordulatú szivattyú; HMV gázüzemű bojlerrel.', '{"hotermelo":{"tipus":"kazan_tabla","kazan":"allando","hely":"belul","energiahordozo":"fosszilis_gaz"},"szabalyozas":{"valasztas":{"alap":"nincs","holeado":{"tipus":"szabad","hofok":"90/70","hatarolo":"kulsofali"},"helyiseg":"nincs","beszabalyozas":{"csovek":"ketcsoves","mod":"nincs","holeadokTobbMint10":false}}},"elosztas":{"hely":"belul","elore":90,"vissza":70},"tarolo":null,"szivattyu":"allando_szabad_20K"}'::jsonb, '{"hotermelo":{"tipus":"egyeb","kod":"gaz_bojler"},"tarolo":{"tipus":"gaz_bojler","hely":"belul"},"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['kockahaz','parasztház','polgari_berhaz'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('hsz_levego_viz_padlo', 'Levegő-víz hőszivattyú + padlófűtés 35/28 + HMV hőszivattyúval', 'Levegő-víz hőszivattyú (táblázati εF = 0,30), nedves fektetésű padlófűtés helyiségenkénti termosztatikus zónaszelepekkel; HMV ugyanazzal a hőszivattyúval indirekt tárolóban.', '{"hotermelo":{"tipus":"hoszivattyu_tabla","forras":"levego_viz","hofok":"35/28"},"szabalyozas":{"valasztas":{"alap":"ref_helyiseg_pi","holeado":{"tipus":"beagyazott","rendszer":"padlo_nedves","hatarolo":"min_szig"},"helyiseg":"termosztatikus","beszabalyozas":{"csovek":"ketcsoves","mod":"statikus_csoportos_dinamikus","holeadokTobbMint10":false}}},"elosztas":{"hely":"belul","elore":35,"vissza":28},"tarolo":null,"szivattyu":"fordulatszam_beagyazott_7K"}'::jsonb, '{"hotermelo":{"tipus":"elektromos_tabla","kod":"hsz_levego"},"tarolo":{"tipus":"indirekt","hely":"belul"},"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['uj_epulet','csaladi_haz'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('hsz_levego_viz_radiator', 'Levegő-víz hőszivattyú + radiátor 55/45 + HMV hőszivattyúval', 'Felújításoknál jellemző: meglévő radiátorok 55/45 °C-on, levegő-víz hőszivattyú (táblázati εF = 0,37).', '{"hotermelo":{"tipus":"hoszivattyu_tabla","forras":"levego_viz","hofok":"55/45"},"szabalyozas":{"valasztas":{"alap":"ref_helyiseg_pi","holeado":{"tipus":"szabad","hofok":"55/45","hatarolo":"kulsofali"},"helyiseg":"termosztatikus","beszabalyozas":{"csovek":"ketcsoves","mod":"statikus_csoportos_nelkul","holeadokTobbMint10":false}}},"elosztas":{"hely":"belul","elore":55,"vissza":45},"tarolo":null,"szivattyu":"fordulatszam_szabad_10K"}'::jsonb, '{"hotermelo":{"tipus":"elektromos_tabla","kod":"hsz_levego"},"tarolo":{"tipus":"indirekt","hely":"belul"},"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['kockahaz_felujitott','csaladi_haz'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('tavho_panel_egycsoves', 'Távhő + egycsöves radiátoros fűtés + távhős HMV cirkulációval', 'Panelos lakótelepek jellemző rendszere: távhő-hőközpont, egycsöves (nem felújított) 90/70 radiátoros fűtés, termosztatikus szelepek, elosztás a pincében (fűtött téren kívül); HMV távhőről cirkulációval.', '{"hotermelo":{"tipus":"tavho","hokozpontokSzama":1},"szabalyozas":{"valasztas":{"alap":"nincs","holeado":{"tipus":"szabad","hofok":"90/70","egycsoves":true,"hatarolo":"kulsofali"},"helyiseg":"termosztatikus","beszabalyozas":{"csovek":"egycsoves","mod":"statikus"}}},"elosztas":{"hely":"kivul","elore":90,"vissza":70},"tarolo":null,"szivattyu":"allando_szabad_20K"}'::jsonb, '{"hotermelo":{"tipus":"tavho","hokozpontokSzama":1},"tarolo":null,"elosztas":{"cirkulacio":true,"hely":"kivul"},"cirkSzivattyu":"ismeretlen"}'::jsonb, array['panel'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('gazkonvektor_villanybojler', 'Gázkonvektorok + elektromos (nappali áramú) villanybojler', 'Régi lakásokban gyakori: kombinált szabályozású hagyományos gázkonvektorok külső falnál, HMV nappali árammal működő villanybojlerrel.', '{"hotermelo":{"tipus":"egyeb","kod":"gazkonvektor_kombinalt"},"szabalyozas":{"kozvetlen":1.2,"forras":"1. függ. 8.14. táblázat – gázkonvektor saját termosztatikus szabályozással, külső falnál"},"elosztas":{"hely":"nincs","elore":0,"vissza":0},"tarolo":null,"szivattyu":null}'::jsonb, '{"hotermelo":{"tipus":"elektromos_tabla","kod":"atfolyos_tarolo"},"tarolo":{"tipus":"el_nappali","hely":"belul"},"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['tegla_tarsashaz','kockahaz','polgari_berhaz'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
insert into gepeszeti_szett (kod, nev, leiras, futes, hmv, jellemzo_epuletek, forras, forras_hivatkozas) values ('tuzifa_kazan_radiator', 'Tűzifa (hasábfa) kazán szabályozóval + radiátor 70/55 + villanybojler', 'Vidéki családi házak: hasábfa tüzelésű kazán, kézi radiátorszelepek, HMV csúcson kívüli árammal működő villanybojlerrel.', '{"hotermelo":{"tipus":"szilard_kazan","kazan":"tuzifa","energiahordozo":"bio_szilard"},"szabalyozas":{"valasztas":{"alap":"nincs","holeado":{"tipus":"szabad","hofok":"70/55","hatarolo":"kulsofali"},"helyiseg":"kezi","beszabalyozas":{"csovek":"ketcsoves","mod":"nincs","holeadokTobbMint10":false}}},"elosztas":{"hely":"belul","elore":70,"vissza":55},"tarolo":null,"szivattyu":"allando_szabad_15K"}'::jsonb, '{"hotermelo":{"tipus":"elektromos_tabla","kod":"atfolyos_tarolo"},"tarolo":{"tipus":"el_csucson_kivul","hely":"belul"},"elosztas":{"cirkulacio":false,"hely":"belul"},"cirkSzivattyu":null}'::jsonb, array['kockahaz','parasztház','csaladi_haz'], 'rendelet', '9/2023 ÉKM számítási módszer, 1. függelék 8–9. fejezet táblázatai (egyszerűsített módszer)');
